import{z as s,x as o,o as r,c as d,q as l,j as B,D as e,d as E,s as i,S as A,b as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"对冲与库存转移","description":"","frontmatter":{"title":"对冲与库存转移","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-hedging-inventory.md","filePath":"quant/mm-hedging-inventory.md","lastUpdated":1791413859000}'),m={name:"quant/mm-hedging-inventory.md"};function p(h,a,u,D,f,c){const t=o("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="对冲与库存转移" tabindex="-1">对冲与库存转移 <a class="header-anchor" href="#对冲与库存转移" aria-label="Permalink to &quot;对冲与库存转移&quot;">​</a></h1><div class="epigraph"><p>偏移是劝对手把货拿走，对冲是自己把风险放到另一条腿上；两条路都有价签，选路的标准是成本，不是习惯。</p><footer>—— 据 Guéant, Lehalle and Fernandez-Tapia, 2013 多资产一节；Almgren and Chriss, Journal of Risk, 2000 整理</footer></div><p><a href="/quant/mm-quote-skew">上一课</a>把偏度写成围绕独立公允价的不对称移动，并强调 \\(q\\) 应是净风险单位。本课把这句话补全：净风险里往往已经有另一条腿。做市商的库存不一定要靠报价偏移消化，可以把风险转移给对冲工具；<a href="/quant/glft-market-making">GLFT</a> 的多资产一节已给出原型——惩罚矩阵吃进协方差，偏度对净暴露。本课写业务口径：何时对冲优于偏移、腿怎么选、带怎么设、账怎么记。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>偏移消化库存的代价是收入与成交强度：为了让别人接货，你要么让价、要么退出另一侧。对冲的代价是执行成本、基差与保证金占用。选择不是二选一而是配比：多小的库存带内用偏度、出带后对冲多少。两种对称的死法：从不设带，每笔成交立刻对冲，做市价差全喂给对冲腿的来回成本；带设太宽，库存带着基差与隔夜缺口一路漂到限额。</p><p><span class="marginnote">直觉类比：对冲带像空调的温控区间——室温（净库存）在区间内不开压缩机（用偏度慢慢调），出了区间才启动。没有带的空调每秒钟开关一次，电费全花在启停上；做市商没有带，价差收入就全喂给对冲腿的来回成本。</span></p><h3 id="净风险向量" tabindex="-1">净风险向量 <a class="header-anchor" href="#净风险向量" aria-label="Permalink to &quot;净风险向量&quot;">​</a></h3><p>状态是向量：现货库存、期货腿、期权 delta 合成一个净暴露，进入同一个惩罚与同一份偏度。漏记对冲腿的后果在 GLFT 一节已警告过：偏度对毛库存再 skew 一遍，等于把已经中性的簿往一边推——盘面表现是「明明对冲了，报价却越来越歪」。</p><p><span class="marginnote">数字实例：现货库存 \\(+100\\) 万、期货腿 \\(-95\\) 万，净暴露只有 5 万。若漏记期货腿、按毛库存偏移报价，等于把近乎中性的簿按 100 万去推——偏度被放大 20 倍，报价歪向一边，接回来的全是逆向选择单。</span></p><p><span class="marginnote">对冲带是一次机会成本的预算：带宽太窄，一次对冲来回（约腿上半个价差加冲击）就能吃掉好几笔做市价差。带宽上限应参照「日成交笔数乘预期价差收入」来定，而不是参照腿的波动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>腿的选择按基差与容量排：同标的期货基差最小、容量最大，是默认腿；高相关 ETF 用于期货不可得或时段不覆盖的场合；期权做市商用自己的 delta 对冲工具。触发规则取阈值带：净暴露超带才动，超带部分对冲固定比例或全额。对冲执行走 <a href="/quant/almgren-chriss">Almgren–Chriss</a> 型切片控制冲击，不是一次市价单砸穿对手簿。成本单列入账：价差、冲击、盯市现金流与保证金占用分开记，保证金口径按<a href="/quant/futures-margin">期货保证金</a>的每日盯市预算——对冲腿是现金流最硬的那条腿，现货未变现时期货腿已经要求付钱。</p>',12)),(r(),B(A,null,{default:e(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22%E5%81%9A%E5%B8%82%E8%85%BF%E6%88%90%E4%BA%A4%22%5D%20--%3E%20GI%5B%22%E6%AF%9B%E5%BA%93%E5%AD%98%22%5D%0A%20%20GI%20--%3E%20NET%5B%22%E5%87%80%E9%A3%8E%E9%99%A9%E5%90%91%E9%87%8F%EF%BC%9A%E5%BA%93%E5%AD%98%20%2B%20%E5%AF%B9%E5%86%B2%E8%85%BF%22%5D%0A%20%20NET%20--%3E%20BAND%7B%22%E8%B6%85%E5%AF%B9%E5%86%B2%E5%B8%A6%EF%BC%9F%22%7D%0A%20%20BAND%20--%3E%7C%E5%90%A6%7C%20SKEW%5B%22%E5%81%8F%E5%BA%A6%E6%B6%88%E5%8C%96%22%5D%0A%20%20BAND%20--%3E%7C%E6%98%AF%7C%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E6%89%A7%E8%A1%8C%EF%BC%9A%E5%88%87%E7%89%87%E6%8E%A7%E5%88%B6%E5%86%B2%E5%87%BB%22%5D%0A%20%20HEDGE%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%E5%85%A5%E8%B4%A6%EF%BC%9A%E4%BB%B7%E5%B7%AE%E3%80%81%E5%86%B2%E5%87%BB%E3%80%81%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20COST%20--%3E%20NET%0A%20%20SKEW%20--%3E%20FILL%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[E("对冲改变做市的收益结构：赚的仍是价差与回扣，付的是基差漂移与对冲执行成本；库存方差被压低之后，同样的风险厌恶下宽度可以收窄、成交强度上升——"),n("strong",null,"对冲通过降风险间接扩量"),E("，这是它优于纯偏度的机制，也是大容量做市几乎都带对冲腿的原因。边界情形由模型内一阶条件给出：带内偏度的边际成本等于对冲的边际成本，带的位置就落在那里。")],-1)),(r(),B(A,null,{default:e(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E8%85%BF%E5%8E%8B%E4%BD%8E%E5%BA%93%E5%AD%98%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20VAR%5B%22%E9%A3%8E%E9%99%A9%E5%8D%A0%E7%94%A8%E4%B8%8B%E9%99%8D%22%5D%0A%20%20VAR%20--%3E%20W%5B%22%E5%90%8C%E6%A0%B7%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%E4%B8%8B%E5%AE%BD%E5%BA%A6%E5%8F%AF%E6%94%B6%E7%AA%84%22%5D%0A%20%20W%20--%3E%20INT%5B%22%E6%88%90%E4%BA%A4%E5%BC%BA%E5%BA%A6%E4%B8%8A%E5%8D%87%22%5D%0A%20%20INT%20--%3E%20INC%5B%22%E4%BB%B7%E5%B7%AE%E4%B8%8E%E5%9B%9E%E6%89%A3%E6%94%B6%E5%85%A5%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20INC%20--%3E%20HEDGE%0A%20%20INC%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E5%9F%BA%E5%B7%AE%E6%BC%82%E7%A7%BB%E4%B8%8E%E6%96%AD%E8%A3%82%E6%97%A5%E8%BF%BD%E4%BF%9D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>相关断裂是这条机制的尾部：正常时两腿相关系数撑起的价差优惠，在相关性归一的当天取消，<a href="/quant/futures-margin">期货保证金</a>口径下追加保证金与对冲失效同时到达，而那正是库存风险最大的时刻。带与限额要按断裂情景而非常态相关性校核。</p><p><span class="marginnote">为什么重要：断裂日最危险的不是对冲失效本身，而是「失效+追保」同时到达——期货腿本来在替你扛风险，那天它却先要求付钱。现金被追保抽走时，你可能被迫在价差最宽的时刻砍现货库存。压力测试必须把这一分钟写进剧本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>涨跌停、停牌与夜盘缺口使对冲腿不可得或延迟，那时只剩偏度与减仓阶梯。保证金螺旋在对冲腿上同样存在，压力日追保优先于新成交。期权做市的 delta 对冲频率与 gamma 损益是衍生品簿自己的问题，见 <a href="/quant/delta-hedge-freq">delta 对冲频率</a>与<a href="/quant/discrete-hedge-error">离散对冲误差</a>；本课只写库存转移的框架，不进入希腊字母管理。对冲成本若不单独入账，绩效归因会把腿上的损耗错记到做市策略头上，那是第九课的口径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>库存消化有两条路：偏移劝对手接货，对冲把风险转移到另一条腿；按边际成本配比。</li><li>状态是净风险向量：对冲腿与库存进同一惩罚、同一份偏度，漏记会双重偏移。</li><li>阈值带内用偏度、出带才对冲；带宽是一次机会成本预算，参照价差收入定。</li><li>对冲降库存方差，间接允许更窄的宽度与更大的量；相关断裂是校核情景。</li><li>对冲成本单列入账，否则归因错位。</li><li>出处：Guéant, Lehalle and Fernandez-Tapia, <em>Mathematics and Financial Economics</em>, 2013；Almgren and Chriss, <em>Journal of Risk</em>, 2000；Black, <em>Journal of Financial Economics</em>, 1976 与 Cox, Ingersoll and Ross, 1981 的盯市口径。</li></ul>',6))])}const g=s(m,[["render",p]]);export{F as __pageData,g as default};
